//! Generated by Codex. Bounded materialization of guest SQL results.

use super::invocation_limits::InvocationContext;
use crate::interface::kernel_sync::get_context;
use mudu::common::result::RS;
use mudu::error::ErrorCode;
use mudu::mudu_error;
use mudu_binding::system::query_invoke::{deserialize_query_param, serialize_query_result};
use mudu_contract::database::result_batch::ResultBatch;
use mudu_contract::database::sql::DBConn;
use mudu_contract::tuple::tuple_field_desc::TupleFieldDesc;
use mudu_contract::tuple::tuple_value::TupleValue;
use serde::Serialize;
use std::io::{self, Write};
use std::sync::Arc;

struct ByteCounter {
    remaining: usize,
}
impl Write for ByteCounter {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        if bytes.len() > self.remaining {
            return Err(io::Error::other("procedure payload budget exhausted"));
        }
        self.remaining -= bytes.len();
        Ok(bytes.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

/// Conservative, allocation-free encoded size check before entering Wasm.
pub(crate) fn check_size(value: &impl Serialize, limit: usize) -> RS<usize> {
    let mut counter = ByteCounter { remaining: limit };
    serde_json::to_writer(&mut counter, value).map_err(|e| {
        mudu_error!(
            ErrorCode::OutOfMemory,
            "procedure payload exceeds budget",
            e
        )
    })?;
    Ok(limit - counter.remaining)
}

fn charge(row: &TupleValue, remaining: &mut usize, control: &InvocationContext) -> RS<()> {
    control.check()?;
    let bytes = check_size(row, *remaining)?;
    let cost = bytes.max(std::mem::size_of::<TupleValue>() + std::mem::size_of_val(row.values()));
    *remaining = remaining.checked_sub(cost).ok_or_else(|| {
        mudu_error!(
            ErrorCode::OutOfMemory,
            "procedure query result exceeds budget"
        )
    })?;
    Ok(())
}

pub(crate) async fn query(input: Vec<u8>, control: Arc<InvocationContext>) -> Vec<u8> {
    let result = query_inner(input, control.clone()).await;
    if result
        .as_ref()
        .is_err_and(|error| error.ec() == ErrorCode::OutOfMemory)
    {
        control.exhaust();
    }
    serialize_query_result(result)
}
async fn query_inner(
    input: Vec<u8>,
    control: Arc<InvocationContext>,
) -> RS<(ResultBatch, TupleFieldDesc)> {
    let (oid, stmt, param) = deserialize_query_param(&input)?;
    let context = get_context(oid)?;
    let mut batch = ResultBatch::new(oid);
    let mut remaining = control.limits.max_output_bytes;
    let desc = match context.db_conn() {
        DBConn::Async(_) => {
            let rows = context.query_raw_async(stmt, param).await?;
            while let Some(row) = rows.next().await? {
                charge(&row, &mut remaining, &control)?;
                batch.add_row(row);
            }
            rows.desc().clone()
        }
        DBConn::Sync(_) => {
            let (rows, desc) = context.query_raw(stmt.as_ref(), param.as_ref())?;
            while let Some(row) = rows.next()? {
                charge(&row, &mut remaining, &control)?;
                batch.add_row(row);
            }
            desc.as_ref().clone()
        }
    };
    batch.set_eof();
    Ok((batch, desc))
}

pub(crate) fn query_sync(input: Vec<u8>, control: Arc<InvocationContext>) -> Vec<u8> {
    match mudu_utils::task_async::run_async(async move { Ok(query(input, control).await) }) {
        Ok(Ok(bytes)) => bytes,
        Ok(Err(error)) | Err(error) => serialize_query_result(Err(error)),
    }
}
